INSERT INTO `activities` (`id`, `created_at`, `updated_at`, `description`, `is_active`, `like_count`, `price`, `recruit_end_at`, `recruit_start_at`, `review_count`, `thumbnail_url`, `title`, `view_count`, `region_id`, `activity_type`, `address`, `approval_status`, `category`, `contact_info`, `end_at`, `external_id`, `organizer`, `source_type`, `source_url`, `start_at`, `target`) VALUES
  (364, '2026-07-09 16:18:46', '2026-07-11 19:14:00', '관계 속에서 나를 지키는 철학의 기술을 주제로 현남숙·진보성 작가/교수가 진행하는 서울도서관 작가힙톡 강연', 1, 0, 0, '2026-07-24 12:00:00', '2026-06-23 12:00:00', 0, 'https://lib.seoul.go.kr/apload/userfiles/images/74563784876643793.png', '7월 작가힙톡 - 관계 속에서 나를 지키는 철학의 기술', 13, 1124, 'EVENT', '서울도서관 1층 생각마루', 'APPROVED', 'HUMANITIES', '02-2133-0238', '2026-07-24 20:30:00', NULL, '서울도서관', 'URL_MANUAL', 'https://lib.seoul.go.kr/lecture/applyDetail/7081', '2026-07-24 19:00:00', '서울도서관 회원'),
  (365, '2026-07-10 09:06:01', '2026-07-10 09:06:03', '웹툰·웹소설 스토리 설계와 작법을 주제로 진행되는 고나무 작가 신간 북토크', 1, 0, 17100, '2026-07-22 00:00:00', NULL, 0, 'https://contents.kyobobook.co.kr/sih/fit-in/458x0/pdt/9791124272503.jpg', '고나무 작가 『팔리는 스토리를 설계하라』 신간 북토크', 0, 1113, 'EVENT', '교보문고 합정점 배움홀', 'APPROVED', 'HUMANITIES', NULL, '2026-07-23 20:30:00', NULL, '교보문고 / 한스미디어', 'URL_MANUAL', 'https://event.kyobobook.co.kr/detail/247339', '2026-07-23 19:00:00', '누구나'),
  (366, '2026-07-10 09:15:15', '2026-07-10 09:15:16', '나의 이야기를 책으로 만드는 총 7회차 독립출판 워크숍', 1, 0, 0, '2026-07-29 00:00:00', '2026-07-21 00:00:00', 0, 'https://bukseongro.or.kr/wp-content/uploads/mangboard/2026/06/18/F5895_%ED%99%88%ED%8E%98%EC%9D%B4%EC%A7%80%20%EC%8D%B8%EB%84%A4%EC%9D%BC-%EC%B6%9C%ED%8C%90.jpg', '독립출판 워크숍 『나의 이야기를 책으로』', 0, 1012, 'PROGRAM', '더폴락', 'APPROVED', 'HUMANITIES', NULL, '2026-09-17 21:30:00', NULL, '북성로', 'URL_MANUAL', 'https://bukseongro.or.kr/m-lecture-list-m1/?vid=112', '2026-08-05 19:30:00', '누구나'),
  (367, '2026-07-10 09:24:07', '2026-07-11 19:57:11', '『집밥력』 출간 기념으로 식사 태도와 웰니스 생활에 대해 이야기 나누는 작가 북토크', 1, 2, 0, '2026-07-19 09:00:00', '2026-07-03 09:00:00', 0, 'https://image.yes24.com/goods/192274401/XL', '『집밥력』 홀썸모먼트 작가 북토크', 4, 1113, 'EVENT', '마포여성동행센터 1층 공간3월8일', 'APPROVED', 'HUMANITIES', NULL, NULL, NULL, '세미콜론', 'URL_MANUAL', 'https://event.yes24.com/273350', '2026-07-21 19:30:00', '누구나'),
  (368, '2026-07-10 09:36:33', '2026-07-10 09:36:36', '자전적 에세이(수필) 쓰기를 통해 글쓰기의 즐거움과 성취감을 경험하는 시간', 1, 0, 0, '2026-07-31 18:00:00', '2026-07-15 10:30:00', 0, 'https://www.l4d.or.kr/attach/editor/img_20260706171225405.jpg', '휘경행복 [26년 3분기 독서·문화] 나를 알아가는 글쓰기', 1, 1111, 'PROGRAM', '휘경행복도서관 3층 프로그램실', 'APPROVED', 'HUMANITIES', '02-2249-9701', '2026-08-25 12:00:00', NULL, '휘경행복도서관', 'URL_MANUAL', 'https://www.l4d.or.kr/hgh/lecturePbDetail.do?lecturePbIdx=13668', '2026-08-04 10:30:00', '20세 이상 성인 12명'),
  (369, '2026-07-10 09:36:33', '2026-07-11 17:20:43', '캔바, 챗GPT 와 같은 AI 도구를 활용하여 그림책 스토리부터 그림책, 주제곡을 제작해보는 작가 등단 풀 코스', 1, 0, 0, '2026-07-31 18:00:00', '2026-07-15 10:30:00', 0, 'https://www.l4d.or.kr/attach/editor/img_20260706171003551.jpg', '휘경행복 [26년 3분기 독서·문화] AI 그림책 창작소', 2, 1111, 'PROGRAM', '휘경행복도서관 3층 프로그램실', 'APPROVED', 'HUMANITIES', '02-2249-9701', '2026-08-29 12:00:00', NULL, '휘경행복도서관', 'URL_MANUAL', 'https://www.l4d.or.kr/hgh/lecturePbDetail.do?lecturePbIdx=13667', '2026-08-01 10:00:00', '14세 이상 청소년~성인 12명'),
